// SEM IA: este fluxo só procura menções e guarda na fila. Custo zero de token.
// Para liberar outro espaço, acrescente parte do nome (minúsculas) em ESPACOS.
// 27/10: piloto CS/Comercial liberado (OK do CEO).
// 27/10: privado CEO ↔ Zezinho — toda mensagem escrita PELO CEO ali vira pedido (sem @). Ninguém mais.
const ESPACOS = ['teste agente de ia', 'comercial & cs'];
const DM_CEO = 'spaces/<SPACE_ID>';
const INICIO_DM = '2026-10-27T13:50:00Z'; // não pega conversas antigas do privado
const CONTA = '<EMAIL>'; // conta que é o Zezinho no Chat
const INICIO = '2026-10-27T12:00:00Z'; // 27/10 9h: início do piloto (não pega menções antigas do Comercial & CS)
const doisDias = new Date(Date.now() - 2 * 86400000).toISOString();
const desde = (doisDias > INICIO ? doisDias : INICIO).replace(/\.\d+Z$/, 'Z');
return [{ json: { ESPACOS, CONTA, desde, DM_CEO, INICIO_DM } }];

const c = $('Config (espaços liberados)').first().json;
const lista = ($input.first().json.spaces || []).filter(s => c.ESPACOS.some(n => String(s.displayName || '').toLowerCase().includes(n)));
// 27/10: privado do CEO com o Zezinho (conversa direta não tem nome, entra pelo id).
if (c.DM_CEO && !lista.some(s => s.name === c.DM_CEO)) lista.push({ name: c.DM_CEO, displayName: 'Privado do CEO' });
return lista.map(s => ({ json: { space: s.name, nome: s.displayName, desde: c.desde, conta: c.CONTA } }));

// Menção = anotação USER_MENTION para a conta do Zezinho, escrita por OUTRA pessoa, ainda não registrada.
// papel: 'ceo' (Redacted Redacted), 'ti' (Redacted) ou 'equipe'. Só ceo/ti podem registrar METAS.
// 27/10: no privado do CEO, toda mensagem escrita pelo CEO (sem @) vira pedido; mensagem de qualquer outra pessoa ali é ignorada.
// 27/10: detecção automática de FECHAMENTO (sem @) DESLIGADA por decisão do Redacted — no Comercial & CS vale só o @.
// Para religar: DETECTAR_FECHAMENTO = true (regra testada: 1ª linha começa com "Fechamento Comercial | Nome" ou "CS | Nome").
const DETECTAR_FECHAMENTO = false;
const cfg = $('Config (espaços liberados)').first().json;
const FECHAMENTO = /^[^\p{L}]*(fechamento\s+(comercial|do dia|cs)|cs)\s*\|\s*\p{L}/iu;
const ESPACO_FECHAMENTO = /comercial\s*&\s*cs/i;
const esp = $('Só espaços liberados').all().map(i => i.json);
const eus = $('Chat - id do Zezinho no espaço').all().map(i => i.json);
const ceos = $('Chat - id do CEO no espaço').all().map(i => i.json);
const tis = $('Chat - id do Redacted no espaço').all().map(i => i.json);
const mems = $('Chat - membros (nomes)').all().map(i => i.json);
const msgs = $('Chat - mensagens recentes').all().map(i => i.json);
const conhecidas = new Set($input.all().map(i => i.json.message_id).filter(Boolean));
const hora = iso => new Date(iso).toLocaleString('pt-BR', { timeZone: 'America/Sao_Paulo', day: '2-digit', month: '2-digit', hour: '2-digit', minute: '2-digit' });
const idDe = r => r && r.member && r.member.name;
const saida = [];
esp.forEach((e, i) => {
  const eu = idDe(eus[i]);
  if (!eu) return;
  const ceo = idDe(ceos[i]), ti = idDe(tis[i]);
  const privadoCeo = e.space === cfg.DM_CEO;
  if (privadoCeo && !ceo) return; // sem confirmar quem é o CEO, não lê o privado
  const lerFechamento = DETECTAR_FECHAMENTO && ESPACO_FECHAMENTO.test(String(e.nome || ''));
  const nomes = {};
  ((mems[i] || {}).memberships || []).forEach(m => { if (m.member && m.member.name) nomes[m.member.name] = m.member.displayName || ''; });
  const lista = (msgs[i] || {}).messages || [];
  const autor = m => (m.sender && (m.sender.displayName || nomes[m.sender.name])) || '?';
  lista.forEach(m => {
    if (!m.sender || m.sender.name === eu || conhecidas.has(m.name)) return;
    const texto = String(m.text || '');
    const marcou = (m.annotations || []).some(a => a.type === 'USER_MENTION' && a.userMention && a.userMention.user && a.userMention.user.name === eu);
    const ehFechamento = lerFechamento && !m.threadReply && texto.length > 200 && FECHAMENTO.test(texto.trim().split('\n')[0]);
    const mencionou = privadoCeo
      ? (m.sender.name === ceo && m.createTime > cfg.INICIO_DM && texto.trim().length > 0)
      : (marcou || ehFechamento);
    if (!mencionou) return;
    const thread = (m.thread && m.thread.name) || '';
    const antes = lista.filter(x => x.thread && x.thread.name === thread && x.createTime < m.createTime).slice(-8)
      .map(x => '[' + hora(x.createTime) + '] ' + autor(x) + ': ' + String(x.text || '').slice(0, 500)).join('\n');
    const anexos = (m.attachment || []).map(a => ({ nome: a.contentName || 'anexo', chat_resource: (a.attachmentDataRef && a.attachmentDataRef.resourceName) || '', drive_file_id: (a.driveDataRef && a.driveDataRef.driveFileId) || '' }));
    const papel = m.sender.name === ceo ? 'ceo' : m.sender.name === ti ? 'ti' : 'equipe';
    const obs = (ehFechamento && !marcou) ? ' [fechamento do dia detectado automaticamente, sem @: avalie como relatório]' : '';
    saida.push({ json: { message_id: m.name, space_id: e.space, space_nome: e.nome, thread_name: thread, autor: autor(m), papel, data_msg: m.createTime, texto: texto.slice(0, 6000), conversa_antes: (antes || '(início da conversa)') + obs, anexos: JSON.stringify(anexos), status: 'nova', tentativas: 0, tipo: '', resultado: '', atualizado_em: new Date().toISOString() } });
  });
});
return saida;
